"""Small date helpers used by the billing service."""

import calendar
from datetime import date, datetime, timedelta, timezone
from zoneinfo import ZoneInfo


def is_leap(year: int) -> bool:
    return calendar.isleap(year)


def month_end(d: date) -> date:
    """Last day of d's month."""
    return d.replace(day=calendar.monthrange(d.year, d.month)[1])


def business_days_between(start: date, end: date) -> int:
    """Weekdays in [start, end), excluding end."""
    n = 0
    d = start
    while d < end:
        if d.weekday() < 5:
            n += 1
        d += timedelta(days=1)
    return n


def to_local(dt: datetime, tz: int | str) -> datetime:
    """Convert an aware UTC datetime to local wall time.

    tz: fixed UTC offset in hours, or an IANA zone name (DST-aware).
    """
    zone = ZoneInfo(tz) if isinstance(tz, str) else timezone(timedelta(hours=tz))
    return dt.astimezone(zone).replace(tzinfo=None)


def parse_iso(s: str) -> datetime:
    """Parse ISO 8601 strings ('Z' or '+00:00' offsets) into aware UTC datetimes."""
    return datetime.fromisoformat(s).astimezone(timezone.utc)


def add_months(d: date, n: int) -> date:
    m = d.month - 1 + n
    year, month = d.year + m // 12, m % 12 + 1
    return d.replace(year=year, month=month, day=min(d.day, calendar.monthrange(year, month)[1]))
